// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. Setup: initialize c with valid addresses.
        // Since C.init requires inited==false, and we want to test the rule after any newGrantProposal call.
        // We can use zero addresses for init because no external calls are made during newGrantProposal, but init is needed for proper state setup.
        // The property we test solely depends on proposalCount and emitted event IDs, so init can use arbitrary addresses.
        vm.assume(recipient != address(0)); // avoid potential issues with zero address recipient? Not strictly needed, but keeps it admissible.
        c.init(address(0x1), address(0x2), address(0x3));

        // 2. Call newGrantProposal; we might call it multiple times to check the rule.
        // capture the proposalCount before the call and the emitted proposalID.
        uint256 countBefore = c.proposalCount();
        vm.recordLogs();
        c.newGrantProposal(recipient, amount);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // Find the NewProposal event: it should have topics signature of NewProposal(address,uint256,string)
        bool foundEvent = false;
        uint256 emittedProposalID = 0;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == keccak256("NewProposal(address,uint256,string)")) {
                // The second topic is the indexed proposalID
                emittedProposalID = uint256(logs[i].topics[2]);
                foundEvent = true;
                break;
            }
        }
        require(foundEvent, "NewProposal event not emitted");

        // 3. Assert: the reference rule: proposalCount must be strictly greater than the emitted proposalID.
        // In correct contract, proposalCount is incremented before event emission, so countAfter = countBefore+1 > emittedID.
        // In buggy, proposalCount never changes, so countAfter = countBefore, and emittedID = countBefore, so countAfter == emittedID, breaking the rule.
        // We must read the current proposalCount after the call.
        uint256 countAfter = c.proposalCount();
        assertTrue(countAfter > emittedProposalID);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint96 amount) public {
        // Initialize the contract with dummy external addresses
        address vader = address(0x1000);
        address usdv = address(0x2000);
        address vault = address(0x3000);
        c.init(vader, usdv, vault);

        // Record the proposalCount before the call
        uint256 countBefore = c.proposalCount();

        // Execute newGrantProposal
        vm.prank(address(0x4000));
        c.newGrantProposal(recipient, uint256(amount));

        // Record the proposalCount after the call
        uint256 countAfter = c.proposalCount();

        // The general invariant: proposalCount must have incremented by exactly 1,
        // and the stored grant must be accessible at the new proposalCount.
        // On the reference contract, mapPID_grant is set after increment, so
        // countAfter == countBefore + 1 and the grant exists at countAfter.
        // On the buggy version, mapPID_grant is written at the old count (countBefore),
        // but proposalCount was incremented before the write, so countAfter == countBefore + 1
        // but the grant is stored at countBefore and the emit uses the old count as well.
        // The bug violates the rule that the grant is stored at the incremented ID.
        // We check that the grant stored at countAfter (the current proposalCount)
        // matches the passed recipient.
        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(countAfter);
        assertTrue(storedRecipient == recipient);
    }
}
